<?php require_once __DIR__.'/config/config.php'; $slug=trim($_GET['slug']??''); $q=db()->prepare('SELECT * FROM pages WHERE slug=? AND enabled=1 LIMIT 1');$q->execute([$slug]);$page=$q->fetch();if(!$page){http_response_code(404);exit('Page not found');}$lang=(($_GET['lang']??'ar')==='en')?'en':'ar';require __DIR__.'/includes/site-header.php'; ?><main class="page"><span>PAGE / <?=e($page['slug'])?></span><h1><?=e($lang==='ar'?$page['title_ar']:$page['title_en'])?></h1><div class="page-content"><?=nl2br(e($lang==='ar'?$page['content_ar']:$page['content_en']))?></div></main><?php require __DIR__.'/includes/site-footer.php';?>
